export const title = "How to Fit a Microphone Arm and Monitor Arm on the Same Small Desk";
export const metaTitle = "How to Fit a Microphone Arm and Monitor Arm on";
export const metaDescription = "Map two bases and two moving paths. Practical measurements, original diagrams and fit checks for audio setup in small workspaces.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-11-03";
